     "title": "美媒：美军开展秘密行动在霍尔木兹海峡打通运油航道",
     "url": "http://finance.eastmoney.com/news/1351,202608203846744817.html",
     "time": "08-20 06:01",
     "ts": 1787176868,
     "summary": "据美国阿克西奥斯新闻网站19日报道，美军已悄悄建立一条进出霍尔木兹海峡的航运通道，确保每天有“数百万桶”石油运出霍尔木兹海峡。 报道援引两名美国官员的话称，这项行动已持续数周。过去两周，每天有15到20艘油轮经由阿曼沿海一条南部航道进出该海峡。美官员称，石油日均运输量持续增长，目前已接近1000万桶，某些夜晚从海湾运出的石油总量甚至达到1500万至2000万桶。 美官员称，虽然经由霍尔木兹海峡运出的石油量仍低于战前水平，但它已对全球供应产生了明显影响。 据报道，这一行动由位于",
     "source": "东方财富资讯",
     "agenda_layer": "market",
